for inst, inicio in zip(isa.data, isa.op_start_times):
    op = inst.operation
    qubits = tuple(isa.find_bit(q).index for q in inst.qubits)
    if op.name == "delay":
        dur = op.duration
    else:
        dur = round(backend.target[op.name][qubits].duration / backend.dt)
    filas.append((op.name, qubits, inicio, dur))
return filas
